return new{frame=Time.frameCount,time=Time.time,state=UnityEngine.Object.FindObjectOfType<GameManager>().CurrentState.ToString(),health=UnityEngine.Object.FindObjectOfType<Base>().currentHealth,towers=UnityEngine.Object.FindObjectsOfType<Tower>().Select(t=>new{t.name,t.Experience,t.Level}).ToArray(),enemies=UnityEngine.Object.FindObjectsOfType<Enemy>().Select(e=>new{e.name,p=e.transform.position.ToString(),health=e.CurrentHealth,onMesh=e.GetComponent<UnityEngine.AI.NavMeshAgent>().isOnNavMesh,path=e.GetComponent<UnityEngine.AI.NavMeshAgent>().pathStatus.ToString()}).ToArray()};
